/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

//---------------------------------------------------------------------------//

UInt32 keeloq_decrypt ( UInt32 data, UInt64 key ) 
{ 
	UInt32 x = data, r; 
	
	for (r = 0; r < 528; r++) 
	{ 
		x = (x<<1)^bit(x,31)^bit(x,15)^(UInt32)bit(key,(15-r)&63)^bit(KeeLoq_NLF,g5(x,0,8,19,25,30)); 
	} 
	return x; 
}


